 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    def separator_lines(values, threshold):
        lines = []
        for i, vals in enumerate(values):
            counts = Counter(vals)
            color, count = counts.most_common(1)[0]
            if color != 0 and count >= len(vals) - threshold and len(counts) > 1:
                lines.append(i)
        return lines
    row_lines = separator_lines(grid, 3)
    col_lines = separator_lines([[grid[r][c] for r in range(h)] for c in range(w)], 3)
    def sample(n, lines):
        result, start = [], 0
        for line in lines:
            if start < line:
                result.append(start)
            result.append(line)
            start = line + 1
        if start < n:
            result.append(start)
        return result
    rows, cols = sample(h, row_lines), sample(w, col_lines)
    return [[grid[r][c] for c in cols] for r in rows]
